import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 78 The last one?","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 78 The last one?","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 77 A successful operation","link":"/life/english/new-concept/book-2/unit-04/lesson-077"},"next":{"text":"第二册：实践与进步 · Lesson 79 By air","link":"/life/english/new-concept/book-2/unit-04/lesson-079"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 77 A successful operation","link":"/life/english/new-concept/book-2/unit-04/lesson-077"},"next":{"text":"第二册：实践与进步 · Lesson 79 By air","link":"/life/english/new-concept/book-2/unit-04/lesson-079"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-078.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-078.md"}'),i={name:"life/english/new-concept/book-2/unit-04/lesson-078.md"};function s(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-78-the-last-one" tabindex="-1">第二册：实践与进步 · Lesson 78 The last one? <a class="header-anchor" href="#第二册-实践与进步-·-lesson-78-the-last-one" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 78 The last one?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>想改变习惯的人面临反复诱惑，计划需要具体行动支撑；练习 stop doing 与 stop to do。本课的语言观察是：stop buying 是停止购买行为，stop to buy 是停下别的活动去购买。改变习惯时还可用 avoid doing，不能把两种 stop 结构当同义。完成学习后，请描述一个准备改变的普通习惯，给出具体行动和追踪办法。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>cigarette</td><td>/ˌsɪɡəˈret/</td><td>n.</td><td>香烟</td><td>a cigarette packet</td></tr><tr><td>quit</td><td>/kwɪt/</td><td>v.</td><td>停止；戒掉</td><td>quit smoking</td></tr><tr><td>effort</td><td>/ˈefət/</td><td>n.</td><td>努力</td><td>make an effort</td></tr><tr><td>craving</td><td>/ˈkreɪvɪŋ/</td><td>n.</td><td>强烈欲望</td><td>a craving for sugar</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>give up a habit — 放弃一个习惯</li><li>make an effort to — 努力做某事，后接原形</li></ul><h2 id="语法讲解-动名词与动词搭配" tabindex="-1">语法讲解：动名词与动词搭配 <a class="header-anchor" href="#语法讲解-动名词与动词搭配" aria-label="Permalink to &quot;语法讲解：动名词与动词搭配&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：stop buying 是停止购买行为，stop to buy 是停下别的活动去购买。改变习惯时还可用 avoid doing，不能把两种 stop 结构当同义。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Jon stopped buying cigarettes on his way to work.</p></blockquote><p>乔恩停止了在上班路上买烟的习惯。</p><p>stopped 为谓语，buying 作动名词宾语，on his way to work 是购买发生的情境。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>对比 stopped buying 与 stopped to buy，to 即使弱读也改变含义。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Jon stopped buying cigarettes on his way to work. He changed his route to avoid the shop. He asked a friend to check on his progress each week.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>描述一个准备改变的普通习惯，给出具体行动和追踪办法。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：stopped 为谓语，buying 作动名词宾语，on his way to work 是购买发生的情境。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：He stopped to buy cigarettes 表示停下来买烟，意思与停止买烟相反。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 buying/to buy：He stopped ___ cigarettes.（不再购买）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> buying</p><p><strong>解析：</strong> 动名词指出被停止的活动。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>他为什么改变路线？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> To avoid the shop.</p><p><strong>解析：</strong> 目的明确，未说商店关闭了。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>翻译 He stopped to buy a newspaper。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 他停下来买了一份报纸。</p><p><strong>解析：</strong> to buy 表停下后要做的目的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词与动词搭配。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-077">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-079">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
